const E_Y0=296, E_K=1.0;  /* eureka: water height in px from bottom; spout level at y=186 */
function eureka(s){
  const lvlY=anim.eureka<0?300:anim.eureka;
  let o=`${C.shadow(530,404,90,7)}<rect x="462" y="304" width="136" height="98" fill="#a37a4d" filter="url(#g-woodgrain)"/><rect x="462" y="304" width="136" height="5" fill="#c9a06c"/>
  <rect x="480" y="150" width="100" height="152" fill="url(#de-acr)"/>
`;
  if(anim.objIn||anim.objY>150){ o+=`<line x1="530" y1="0" x2="530" y2="${anim.objY-14}" stroke="#e8e2d0" stroke-width="1"/>`+irrShape(st.irr,530,anim.objY,1.1); }
  o+=`<g clip-path="url(#de-eclip)"><rect x="480" y="${lvlY}" width="100" height="${310-lvlY}" fill="url(#g-water)"/>${anim.eureka>0?`<rect x="480" y="${lvlY-1}" width="100" height="2.5" fill="#e8f6fc" opacity=".6"/>`:""}</g>`;
  o+=`<rect x="480" y="150" width="100" height="152" fill="none" stroke="#e9f5f9" stroke-opacity=".75" stroke-width="1.5"/><rect x="485" y="158" width="4" height="138" fill="#fff" opacity=".35"/>
  <path d="M579 182 L640 194 L640 202 L579 192Z" fill="url(#de-acr)" stroke="#e9f5f9" stroke-opacity=".7"/>
  ${anim.stream>0?`<path d="M640 200 Q646 206 650 ${Math.max(214,cylY(anim.cylLvl)-2)}" stroke="#bfe3f2" stroke-opacity=".9" stroke-width="${2+anim.stream*2}" fill="none" stroke-linecap="round"/>`:""}
  ${st.done.cyl?cylinder(652,404,392,3.2,15,50,LIQ.water,anim.cylLvl,"de-cl"):""}
  <text x="530" y="146" text-anchor="middle" font-family="Arial" font-size="8" fill="#3d474b">eureka can</text>`;
  return o; }
const cylY=ml=>392-ml*3.2;
function beaker(L){ const p=anim.pour; const tx=250-156*p, ty=330-235*p, rot=-105*p;
  return `<g transform="translate(${tx} ${ty}) rotate(${rot} 32 0)">${p<.05?C.shadow(32,72,46,5):""}<path d="M0 0 H64 V64 Q64 70 58 70 H6 Q0 70 0 64Z" fill="url(#g-glass)"/>
  <rect x="2" y="${p>.5?2:22}" width="60" height="${p>.5?20:46}" fill="${L.col}" opacity="${L.op*(st.done.pour?0:1)}"/><path d="M0 0 H64 V64 Q64 70 58 70 H6 Q0 70 0 64Z" fill="none" stroke="#e9f5f9" stroke-opacity=".75" stroke-width="1.4"/>
  <path d="M-4 0 H4" stroke="#e9f5f9" stroke-width="2"/><text x="32" y="50" text-anchor="middle" font-family="Arial" font-size="7" fill="#fff" opacity=".8">250 ml</text></g>
  ${anim.stream>0&&st.mode==="liq"?`<path d="M134 127 Q${PANX+2} 170 ${PANX} ${316-anim.liqLvl*1.7}" stroke="${L.col}" stroke-opacity=".9" stroke-width="${1.5+anim.stream*2.5}" fill="none" stroke-linecap="round"/>`:""}
  <text x="282" y="420" text-anchor="middle" font-family="Arial" font-size="8" fill="#c9d2d5">${p<.05?L.name:""}</text>`; }
