  $("#ac-thead").innerHTML=`<tr><th>${f?"F / N":"m / kg"}</th>${f?"":"<th>1/m / kg⁻¹</th>"}<th>t₁ / s</th><th>t₂ / s</th><th>t₁₂ / s</th><th>v₁ / m s⁻¹</th><th>v₂ / m s⁻¹</th><th>a / m s⁻²</th><th></th></tr>`;
  const d=f?st.dataF:st.dataM;
  rows($("#ac-tbody"),d.map(r=>[f?fx(r.F,3):fx(r.M,3),...(f?[]:[fx(1/r.M,2)]),fx(r.t1,3),fx(r.t2,3),fx(r.t12,3),fx(CARD/r.t1,3),fx(CARD/r.t2,3),fx(acc(r),3)]),"Release the trolley to record a run.",f?7:8,true);
